package main

import (
	"encoding/json"
	"os"
)

var cases []struct{ Scores map[string]int; Name string }
func main() {
 if err := json.Unmarshal([]byte(os.Args[1]), &cases); err != nil { panic(err) }
 enc := json.NewEncoder(os.Stdout)
 for _, in := range cases { var out any; v, ok := lookup(in.Scores, in.Name); out = []any{v, ok}; if err := enc.Encode(out); err != nil { panic(err) } }
}
